import { parseModel, type ModelDef, type ModelInput } from '../models/schema';
import type { EnvironmentPreset, GravityMode } from '../app/settings';
import { wreckingBall } from '../models/builtin/machines';
import { dominoLine, galtonBalls } from '../models/builtin/structures';
import { orbitalSpeed } from '../physics/gravity';
import { part, sphere } from '../models/builtin/helpers';

type V3 = [number, number, number];

export interface ScenarioPlacement {
  /** Library model id, or an inline model generated by the scenario. */
  model: string | ModelDef;
  position?: V3;
  rotation?: V3;
  velocity?: V3;
}

export interface Scenario {
  id: string;
  name: string;
  description: string;
  physics?: Partial<{ gravityMode: GravityMode; gravity: number; gravityPreset: string; G: number; windX: number; windZ: number; timeScale: number; airDrag: boolean }>;
  render?: Partial<{ environment: EnvironmentPreset; sunElevation: number; sunAzimuth: number; trails: boolean; exposure: number }>;
  ground?: boolean;
  camera?: { position: V3; target: V3 };
  placements: () => ScenarioPlacement[];
}

const inline = (m: ModelInput) => parseModel(m);

function orbitBody(id: string, name: string, radius: number, material: string, density: number): ModelDef {
  return inline({ id, name, category: 'Space', parts: [part('b', [sphere(radius)], { material, density, angularDamping: 0, linearDamping: 0 })] });
}

