/** Chenciner–Montgomery figure-eight initial conditions (G = m = 1), scaled to sandbox units. */
export function figure8Placements(): ScenarioPlacement[] {
  const L = 2.5; // length scale (m)
  const mass = 625; // kg per body
  const radius = 0.18;
  const density = mass / ((4 / 3) * Math.PI * radius ** 3);
  const Geff = 0.01 * 1; // G_BASE × G multiplier 1
  const vs = Math.sqrt((Geff * mass) / L);
  const x1: [number, number] = [-0.97000436, 0.24308753];
  const v3: [number, number] = [-0.93240737, -0.86473146];
  const bodies: { p: [number, number]; v: [number, number]; mat: string }[] = [
    { p: x1, v: [-v3[0] / 2, -v3[1] / 2], mat: 'neon' },
    { p: [-x1[0], -x1[1]], v: [-v3[0] / 2, -v3[1] / 2], mat: 'neon-pink' },
    { p: [0, 0], v: v3, mat: 'sun' },
  ];
  const y = 3;
  return bodies.map((b, i) => ({
    model: orbitBody(`f8-${i}`, `Body ${i + 1}`, radius, b.mat, density),
    position: [b.p[0] * L, y, b.p[1] * L] as V3,
    velocity: [b.v[0] * vs, 0, b.v[1] * vs] as V3,
  }));
}

export const FIGURE8_PERIOD = 6.32591398 * Math.sqrt(2.5 ** 3 / (0.01 * 625));
